INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Sobre o manejo do empiema pleural agudo, a videotoracoscopia (VATS) deve ser considerada precocemente em qual circunstância?", "options": {"a": "Se o paciente for tabagista inveterado.", "b": "Apenas se o paciente estiver em choque séptico refratário.", "c": "No primeiro dia de todo derrame parapneumônico simples.", "d": "Substituindo o uso de antibióticos venosos.", "e": "Quando houver falha na drenagem tubular e antibioticoterapia (persistência de loculações radiológicas e febre) após 3-7 dias."}, "answer": "e", "rationale": "A VATS precoce (nos primeiros 7 dias de infecção pleural persistente) é altamente eficaz para limpar loculações (debris de fibrina) e garantir a reexpansão pulmonar antes que a fibrina se transforme em tecido fibroso denso (fase de organização), o que exigiria uma cirurgia muito maior (toracotomia aberta).", "option_rationales": {"a": "Incorreta. Status tabágico não é indicação cirúrgica isolada.", "b": "Incorreta. No choque a estabilização e drenagem rápida são prioridades.", "c": "Incorreta. Exagerado para casos simples que respondem a atb.", "d": "Incorreta. Antibióticos são fundamentais.", "e": "Correta. Janela de oportunidade para tratamento minimamente invasivo eficaz."}, "difficulty": "media", "tags": ["Pneumologia", "Cirurgia Torácica", "Empiema", "Manejo"]}', 100, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 60 anos apresenta derrame pleural bilateral e ascite. A análise do líquido pleural revela: Transudato, Glicose normal, ausência de células malignas. A dosagem de hormônio tireoestimulante (TSH) é de 85 mUI/L. Qual a denominação correta para o derrame pleural neste contexto de hipotireoidismo severo?", "options": {"a": "Pseudotumor de Myx (Myxoma pleural).", "b": "Derrame Mixedematoso.", "c": "Síndrome de Hoffman.", "d": "Anasarca Endócrina.", "e": "Efunsão mista trans-exsudativa."}, "answer": "b", "rationale": "O derrame mixedematoso ocorre no hipotireoidismo severo por aumento da permeabilidade capilar e redução da drenagem linfática. Embora possa ser exsudato em alguns casos raros, é classicamente um transudato que resolve apenas com a reposição hormonal (levotiroxina).", "option_rationales": {"a": "Incorreta. Myxoma é um tumor cardíaco.", "b": "Correta. Nome clínico do derrame por mixedema.", "c": "Incorreta. Síndrome de Hoffman é a miopatia do hipotireoidismo no adulto.", "d": "Incorreta. Termo genérico.", "e": "Incorreta. Termo não utilizado."}, "difficulty": "media", "tags": ["Pneumologia", "Endocrinologia", "Hipotireoidismo", "Mixedema"]}', 101, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Sobre o manejo da Pleurite Tuberculosa, qual o papel do uso adjuvante de Corticosteroides sistêmicos?", "options": {"a": "Causam cegueira se usados com etambutol.", "b": "Reduzem o tempo de cura bacteriológica.", "c": "Substituem a rifampicina nos primeiros 2 meses.", "d": "São obrigatórios para todos os pacientes visando esterilização da pleura.", "e": "Reduzem a febre e a dor mais rapidamente, mas não há evidência robusta de que previnam o espessamento pleural residual significativo a longo prazo."}, "answer": "e", "rationale": "O uso de corticoide (Prednisona) pode ser feito para alívio rápido de sintomas (febre, dor) em pacientes muito sintomáticos. No entanto, meta-análises mostram que não há benefício claro na prevenção de fibrose pleural sequelar ou melhora da função pulmonar final em comparação ao esquema RIPE isolado.", "option_rationales": {"a": "Incorreta. Etambutol causa neurite óptica isoladamente; corticoide não agrava essa toxicidade específica desta forma.", "b": "Incorreta. Corticoides podem até retardar o clearance se não usados com TB sensível.", "c": "Incorreta. Não substituem o esquema bactericida/esterilizante.", "d": "Incorreta. Não são obrigatórios.", "e": "Correta. Consenso atual baseado em evidências de ensaios clínicos."}, "difficulty": "media", "tags": ["Pneumologia", "Tuberculose", "Terapêutica", "Corticoides"]}', 102, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Sobre o mecanismo de produção do líquido pleural na fisiologia normal (Ponto de vista de Starling), qual a afirmação correta de acordo com os conceitos modernos?", "options": {"a": "O líquido é produzido na pleura visceral e absorvido na pleura parietal.", "b": "O líquido é produzido principalmente pelos capilares da pleura parietal e absorvido predominantemente pelos linfáticos estomais da pleura parietal.", "c": "A drenagem linfática pleural não tem influência no volume do líquido.", "d": "A pleura visceral é a principal responsável pela absorção linfática do líquido pleural no ser humano.", "e": "A pressão oncótica das proteínas no espaço pleural é zero em condições normais."}, "answer": "b", "rationale": "Conceitos clássicos sugeriam produção na parietal e absorção na visceral. No entanto, estudos modernos mostram que no ser humano a pleura parietal (suprida pela circulação sistêmica e com maior gradiente de pressão) é responsável tanto pela maior parte da produção quanto pela quase totalidade da absorção (via linfáticos estomais da pleura parietal inferior e diafragmática).", "option_rationales": {"a": "Incorreta. Conceito antigo e anatomicamente impreciso para humanos.", "b": "Correta. Visão fisiológica contemporânea da dinâmica de fluidos pleural.", "c": "Incorreta. O sistema linfático é o principal regulador do equilíbrio entre entrada e saída de líquido.", "d": "Incorreta. A pleura visceral no humano é espessa e sua drenagem linfática é voltada para o parênquima/hilo, não para o espaço pleural.", "e": "Incorreta. Existe uma pequena quantidade de proteínas (cerca de 1-1,5 g/dL) no líquido normal."}, "difficulty": "dificil", "tags": ["Pneumologia", "Fisiologia", "Starling", "Linfáticos"]}', 103, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "O ''Pseudoquilotórax'' (Derrame de Colesterol) é caracterizado pelo acúmulo de cristais de colesterol no espaço pleural. Diferente do quilotórax, quais doenças estão classicamente associadas a esse quadro crônico?", "options": {"a": "Insuficiência Cardíaca e Síndrome Nefrótica.", "b": "Trauma torácico e Cirurgia Cardíaca.", "c": "Artrite Reumatoide e Tuberculose de longa data.", "d": "Linfoma e Carcinoma de Mama.", "e": "Pneumonia Estafilocócica e HIV."}, "answer": "c", "rationale": "O pseudoquilotórax ocorre em processos pleurais crônicos onde o espessamento das pleuras impede a absorção dos lipídios provenientes da quebra de células inflamatórias e hemácias. TB de longa data (antes tratada apenas com colapsoterapia) e Artrite Reumatoide crônica são as causas clássicas.", "option_rationales": {"a": "Incorreta. Causas de transudato.", "b": "Incorreta. Causas de quilotórax agudo.", "c": "Correta. Padrão clínico de doenças inflamatórias crônicas da pleura.", "d": "Incorreta. Neoplasias causam mais quilotórax (por obstrução do ducto) que pseudo.", "e": "Incorreta. Não associadas à cronicidade necessária para acumular cristais de colesterol."}, "difficulty": "media", "tags": ["Pneumologia", "Bioquímica", "Colesterol", "Pseudochylothorax"]}', 104, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual a principal limitação do uso da ''Escrituração por Imagem'' (Escore RAPID) no manejo clínico dos derrames pleurais?", "options": {"a": "É impossível de decorar.", "b": "O escore RAPID (Renal, Age, Purulence, Infection source, Dietary) é validado especificamente para prever mortalidade em pacientes com Empiema/Derrame Parapneumônico, não sendo aplicável para transudatos ou câncer.", "c": "Exige ressonância magnética nuclear.", "d": "Só funciona para câncer.", "e": "Só pode ser usado por cirurgiões."}, "answer": "b", "rationale": "O escore RAPID ajuda a estratificar o risco de morte em 3 meses para empiema pleural. Variáveis como Ureia (Renal), Idade, Purulência do líquido, Local da infecção (Comunitário vs Nosocomial) e Nível de Albumina são as ferramentas de cálculo. Conhecer seu público alvo é essencial.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Validação clínica específica de escores prognósticos.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "dificil", "tags": ["Pneumologia", "Escore RAPID", "Empiema", "Prognóstico"]}', 105, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Durante uma toracoscopia diagnóstica em um paciente com derrame pleural exsudativo linfocítico unilateral, o cirurgião observa múltiplos pequenos nódulos esbranquiçados espalhados pelas superfícies pleural parietal e visceral, com aspecto de ''grãos de milheto''. Esse achado macroscópico é altamente sugestivo de:", "options": {"a": "Tuberculose Pleural (forma miliar).", "b": "Talcose pleural iatrogênica.", "c": "Mesotelioma maligno em estágio inicial.", "d": "Carcinomatose pleural de origem ovariana.", "e": "Sarcoidose de acometimento pleural."}, "answer": "a", "rationale": "A visualização de ''grânulos'' ou ''grãos de milho'' na superfície pleural durante a VATS é a marca macroscópica da tuberculose pleural. A biópsia desses nódulos confirmará o diagnóstico através da presença de granulomas com necrose de caseificação.", "option_rationales": {"a": "Correta. É o achado clássico da TB pleural na toracoscopia.", "b": "Incorreta. A talcose ocorre após pleurodese e as partículas de talco são irregulares e frequentemente encapsuladas por fibrina mais densa.", "c": "Incorreta. O mesotelioma costuma apresentar espessamento pleural difuso ou massas maiores, não pequenos grânulos uniformes.", "d": "Incorreta. A carcinomatose costuma apresentar nódulos maiores, irregulares e muitas vezes com implantes umbilicados.", "e": "Incorreta. A sarcoidose pleural é rara; embora granulomatosa, a apresentação miliar macroscópica na pleura é excepcional."}, "difficulty": "dificil", "tags": ["Pneumologia", "Tuberculose", "Toracoscopia", "Semiologia Pleural"]}', 106, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual medicação anti-hipertensiva está associada ao Lupus Induzido por Drogas (Drug-Induced Lupus - DIL), cursando frequentemente com derrame pleural exsudativo e anticorpos anti-histona positivos no soro?", "options": {"a": "Hidralazina.", "b": "Losartana.", "c": "Hidroclorotiazida.", "d": "Enalapril.", "e": "Amlodipino."}, "answer": "a", "rationale": "A Hidralazina é uma das drogas mais clássicas associadas ao Lúpus Induzido por Drogas. Diferente do LES idiopático, o DIL costuma poupar o rim e o sistema nervoso central, manifestando-se principalmente por sintomas constitucionais, serosites (pericardite e pleurite) e artralgias. O marcador sorológico principal é o anticorpo anti-histona.", "option_rationales": {"a": "Correta. Causa clássica de pleurite lúpica iatrogênica.", "b": "Incorreta. Não associada.", "c": "Incorreta. Não associada.", "d": "Incorreta. Não associada ao DIL.", "e": "Incorreta. Pode dar edema de MMII, mas não lúpus."}, "difficulty": "media", "tags": ["Pneumologia", "Reumatologia", "Derrame Iatrogênico", "DIL"]}', 107, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A medição do pH do líquido pleural em pacientes com Derrame Pleural Maligno apresenta qual valor prognóstico?", "options": {"a": "pH baixo indica que o paciente deve receber antibióticos.", "b": "pH alcalino (> 7,6) indica cura iminente.", "c": "Indica o tipo histológico do câncer (ex: epidermoide vs adenocarcinoma).", "d": "pH < 7,30 está associado a uma menor sobrevida e menor chance de sucesso na pleurodese química.", "e": "Nenhum valor."}, "answer": "d", "rationale": "No derrame maligno, o pH ácido reflete uma alta carga metabólica tumoral, pleura mais infiltrada e espessada. Isso correlaciona-se com menor tempo de sobrevida global desses pacientes e com taxas de falha de pleurodese de até 50-70%.", "option_rationales": {"a": "Incorreta. Ph baixo no câncer não indica infecção, mas sim atividade tumoral/inflamatória.", "b": "Incorreta. pH alcalino é raro e sem este significado.", "c": "Incorreta. Ph baixo ocorre em qualquer subtipo histológico avançado.", "d": "Correta. pH baixo = Doença mais agressiva/avançada na pleura.", "e": "Incorreta. Tem alto valor prognóstico validado."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "Prognóstico", "pH Pleural"]}', 108, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Em pacientes com Sarcoidose, o derrame pleural é uma manifestação rara. Quando ocorre, o diagnóstico diferencial mais difícil com base apenas no líquido pleural (exsudato linfocítico) é com:", "options": {"a": "Derrame Parapneumônico Simples.", "b": "Tuberculose Pleural.", "c": "Insuficiência Cardíaca Congestiva.", "d": "Urinotórax.", "e": "Atelectasia de base."}, "answer": "b", "rationale": "Ambas (Sarcoidose e Tuberculose) são doenças granulomatosas que produzem exsudatos linfocíticos. Embora o ADA ajude (muito alto na TB, baixo/médio na Sarcoidose), o perfil citológico pode ser idêntico, exigindo biópsia e cultura para diferenciação definitiva.", "option_rationales": {"a": "Incorreta. Pneumonia dá líquido neutrofílico.", "b": "Correta. Principal desafio diagnóstico pelo perfil inflamatório granulomatoso similar.", "c": "Incorreta. ICC dá transudato.", "d": "Incorreta. Urinotórax é transudato ácido.", "e": "Incorreta. Atelectasia dá transudatos pequenos."}, "difficulty": "media", "tags": ["Pneumologia", "Diagnóstico Diferencial", "Sarcoidose", "Tuberculose"]}', 109, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual a principal causa de Derrame Pleural Persistente após cirurgia de Revascularização do Miocárdio (CABG) com uso da artéria mamária interna?", "options": {"a": "Infecção por pseudomonas sempre.", "b": "Tuberculose reativada pelo trauma.", "c": "Síndrome de Post-Cardiotomia (inflamação imunológica) ou distúrbios de drenagem linfática/venosa local no hemitórax operado.", "d": "Rejeição ao fio de sutura.", "e": "Hipotireoidismo cirúrgico."}, "answer": "c", "rationale": "Derrames pleurais pós-CABG (especialmente à esquerda devido ao uso da mamária esquerda) são muito comuns. Podem ser precoces (por sangramento ou trauma cirúrgico) ou tardios (Síndrome de Dressler/Pós-cardiotomia), respondendo frequentemente a anti-inflamatórios ou corticoides.", "option_rationales": {"a": "Incorreta. O derrame costuma ser estéril inflamatório.", "b": "Incorreta.", "c": "Correta. Evolução frequente e bem descrita na cirurgia cardíaca.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Pneumologia", "Cirurgia Cardíaca", "CABG", "Dressler"]}', 110, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Em relação ao diagnóstico diferencial do derrame pleural com baixos níveis de glicose (< 60 mg/dL), qual das seguintes condições costuma apresentar os níveis MAIS BAIXOS de glicose (frequentemente próximos de zero)?", "options": {"a": "Derrame Pleural por Artrite Reumatoide.", "b": "Derrame Parapneumônico Simples.", "c": "Derrame Pleural Maligno.", "d": "Tuberculose Pleural.", "e": "Lúpus Eritematoso Sistêmico."}, "answer": "a", "rationale": "A Artrite Reumatoide (AR) é a condição que produz a maior queda de glicose no líquido pleural, muitas vezes atingindo valores indetectáveis (0 a 10 mg/dL). O mecanismo envolve um bloqueio no transporte de glicose através da pleura inflamada e espessada.", "option_rationales": {"a": "Correta. AR e Empiema organizado são as causas de glicose ''zero'' ou quase zero.", "b": "Incorreta. No derrame simples a glicose costuma ser normal.", "c": "Incorreta. No câncer, a glicose baixa é sinal de grande carga tumoral, variando geralmente entre 30-50 mg/dL.", "d": "Incorreta. Na TB, a glicose é baixa, mas costuma variar entre 40-60 mg/dL.", "e": "Incorreta. No LES a glicose costuma ser normal ou levemente reduzida, raramente tão baixa quanto na AR."}, "difficulty": "dificil", "tags": ["Pneumologia", "Líquido Pleural", "Bioquímica", "Artrite Reumatoide"]}', 111, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente submetido à colocação de cateter venoso central na veia subclávia esquerda desenvolve derrame pleural esquerdo volumoso logo após o início da infusão de dieta parenteral (NPT). O líquido pleural coletado tem aspecto leitoso e os valores de glicose e lipídios são idênticos à solução de NPT infundida. Qual a complicação?", "options": {"a": "Empiema por contaminação da dieta.", "b": "Infusão intrapleural inadvertida devido à migração ou mau posicionamento do cateter venoso central (Quilotórax iatrogênico fictício).", "c": "Derrame de colesterol iatrogênico.", "d": "Quilotórax por lesão do ducto torácico.", "e": "Pseudoquilotórax agudo."}, "answer": "b", "rationale": "Este é um quadro clássico de complicação de acesso venoso central. O cateter perfura a veia e a pleura, e a infusão de lípidos (contidos na NPT) simula macroscopicamente um quilotórax. A análise química igual à do frasco de infusão confirma o acidente de punção/posicionamento.", "option_rationales": {"a": "Incorreta. Quadro súbito logo após o início da infusão não é tempo para empiema.", "b": "Correta. Acidente evitável com RX de controle pós-punção.", "c": "Incorreta. Termo não aplicável.", "d": "Incorreta. O ducto torácico desemboca na junção subclávia/jugular esquerda; sua lesão daria quilo real, mas o quadro imediato pós-infusão com química idêntica aponta para o cateter no espaço pleural.", "e": "Incorreta. Pseudoquilotórax leva meses para se formar."}, "difficulty": "facil", "tags": ["Pneumologia", "Terapia Intensiva", "Iatrogenia", "NPT"]}', 112, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Erdheim-Chester Disease'' é uma histiocitose de células não-Langerhans rara. Qual o achado radiológico extratorácico clássico que, se associado a derrame pleural e espessamento pleural, sugere o diagnóstico?", "options": {"a": "Agenesia de baço.", "b": "Escoliose grave.", "c": "Infiltração perirrenal (''Hairy Kidney'' - rim cabeludo) e osteosclerose bilateral de ossos longos.", "d": "Cistos renais simples.", "e": "Nódulos hepáticos gigantes."}, "answer": "c", "rationale": "A doença de Erdheim-Chester é uma neoplasia mieloide multissistêmica. O envolvimento pleural (espessamento e derrame) ocorre em até 20% dos casos. O achado patognomônico é a infiltração de gordura perirrenal por histiócitos (Hairy Kidney) e a esclerose óssea simétrica em fêmur ou tíbia.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta.", "c": "Correta. Associação clínica rara mas clássica em provas de alto nível.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "dificil", "tags": ["Pneumologia", "Hematologia", "Erdheim-Chester", "Radiologia"]}', 113, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "As placas pleurais são a manifestação radiológica mais comum da exposição ao asbesto. Qual a localização preferencial dessas placas?", "options": {"a": "Pleura visceral perihilar.", "b": "Pleura parietal lateral, posterior e superfície diafragmática (poupando os ápices e os ângulos costofrênicos).", "c": "Ápices pulmonares e pleura mediastinal.", "d": "Cisuras interlobares exclusivamente.", "e": "Traqueia e grandes brônquios."}, "answer": "b", "rationale": "As placas de asbesto são calcificações focais na pleura parietal. Elas têm predileção pelas zonas inferiores e médias das paredes torácicas lateral e posterior, além do diafragma. Elas classicamente poupam os ápices pulmonares e os recessos costofrênicos, o que ajuda a diferenciar de sequelas de TB ou empiema.", "option_rationales": {"a": "Incorreta. Local de linfonodomegalia na sarcoidose.", "b": "Correta. Distribuição anatômica característica do asbesto.", "c": "Incorreta. Ápice é mais comum para sequela de TB.", "d": "Incorreta. Cisuras podem ser acometidas, mas a parietal é o alvo principal.", "e": "Incorreta. Não acometem vias aéreas de grande calibre."}, "difficulty": "dificil", "tags": ["Pneumologia", "Doença Ocupacional", "Asbesto", "Radiologia"]}', 114, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "O Urinotórax é uma condição rara onde a urina se acumula no espaço pleural, geralmente por obstrução urinária ou trauma urológico. Qual das alternativas descreve as características bioquímicas típicas desse líquido?", "options": {"a": "Transudato com relação Creatinina Pleural / Creatinina Sérica > 1,0.", "b": "Transudato com odor fétido e pH ácido (< 7,0).", "c": "Exsudato neutrofílico com pH alcalino (> 8,0).", "d": "Líquido de aspecto leitoso rico em amônia.", "e": "Exsudato com glicose zero e ADA elevado."}, "answer": "a", "rationale": "O urinotórax é a única causa de transudato que se apresenta com pH ácido (< 7,30). O diagnóstico é confirmado pela relação creatinina pleural / creatinina sérica > 1,0 (frequentemente > 5,0). O líquido mimetiza a química da urina.", "option_rationales": {"a": "Correta. A relação de creatinina é o achado confirmatório.", "b": "Incorreta. Embora o pH seja ácido, o líquido pode ter odor de urina, não necessariamente ''fétido'' de infecção.", "c": "Incorreta. O urinotórax é classicamente um transudato.", "d": "Incorreta. Aspecto leitoso sugere quilotórax.", "e": "Incorreta. Características de TB ou artrite reumatoide."}, "difficulty": "dificil", "tags": ["Pneumologia", "Urologia", "Urinotórax", "Diagnóstico Diferencial"]}', 115, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A Síndrome de Doege-Potter é uma síndrome paraneoplásica rara associada a um tumor específico da pleura. Ela se caracteriza por episódios de hipoglicemia grave devido à produção de uma forma anômala de IGF-2 (Insulin-like growth factor 2) pelo tumor. Qual é o tumor pleural caracteristicamente associado a essa síndrome?", "options": {"a": "Linfoma Pleural Primário.", "b": "Adenocarcinoma de pulmão invasivo.", "c": "Tumor Fibroso Solitário da Pleura (TFSP).", "d": "Mesotelioma Pleural Maligno.", "e": "Timoma com implante pleural."}, "answer": "c", "rationale": "O Tumor Fibroso Solitário da Pleura (anteriormente chamado de mesotelioma benigno, embora possa ser maligno) é um tumor mesenquimal que pode cursar com a Síndrome de Doege-Potter. A hipoglicemia ocorre pela secreção de ''big'' IGF-2, que estimula os receptores de insulina.", "option_rationales": {"a": "Incorreta. Não associado.", "b": "Incorreta. Adenocarcinoma não produz IGF-2.", "c": "Correta. Associação clássica da questão de prova de alto nível.", "d": "Incorreta. Mesotelioma não causa hipoglicemia paraneoplásica.", "e": "Incorreta. Timomas podem causar Miastenia Gravis, mas não Doege-Potter."}, "difficulty": "dificil", "tags": ["Pneumologia", "Oncologia", "Síndromes Paraneoplásicas", "TFSP"]}', 116, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Pleurodese Medicinal'' com Doxiciclina ou Minociclina é uma alternativa ao talco. Qual é a principal desvantagem desses agentes químicos?", "options": {"a": "São absorvidos e causam hepatite tóxica.", "b": "Só podem ser usados em crianças.", "c": "Não existem no Brasil.", "d": "Causam escurecimento dos dentes para sempre.", "e": "Menor taxa de sucesso na sínfise pleural (cerca de 60-70%) em comparação ao talco (85-90%) e maior dor local."}, "answer": "e", "rationale": "Agentes esclerosantes derivados de tetraciclinas são menos potentes que o talco para gerar a fibrose sínfiseal necessária e costumam causar muita dor pleural durante a instilação, exigindo anestesia local potente ou sedação.", "option_rationales": {"a": "Incorreta. Absorção sistêmica é desprezível para causar hepatite.", "b": "Incorreta. Uso em adultos para pleurodese paliativa.", "c": "Incorreta. Estão disponíveis.", "d": "Incorreta. Isso ocorre por uso oral em crianças em fase de dentição, não por uso pleural.", "e": "Correta. Eficácia inferior documentada."}, "difficulty": "media", "tags": ["Pneumologia", "Pleurodese", "Doxiciclina", "Terapêutica"]}', 117, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 40 anos é admitido com hemotórax traumático após acidente automobilístico. O dreno de tórax é inserido em 5º espaço intercostal, com saída imediata de 1.200 mL de sangue. Nas 2 horas seguintes, a drenagem mantém-se constante em 250 mL/h. O paciente apresenta-se taquicárdico e hipotenso apesar de reposição volêmica. Qual a conduta cirúrgica imediata?", "options": {"a": "Realizar videotoracoscopia (VATS) para identificação do sangramento.", "b": "Administrar ácido tranexâmico e complexo protrombínico imediatamente.", "c": "Realizar arteriografia com embolização das artérias intercostais.", "d": "Encaminhar para toracotomia de urgência.", "e": "Manter observação e drenagem, aguardando 12h para estabilização."}, "answer": "d", "rationale": "As indicações clássicas para toracotomia de urgência no hemotórax traumático incluem: 1) Drenagem imediata > 1.500 mL (ou > 20 mL/kg); ou 2) Drenagem mantida > 200 mL/h nas primeiras 2 a 4 horas; ou 3) Instabilidade hemodinâmica sem outra causa. Este paciente preenche o critério de débito mantido e instabilidade hemodinâmica.", "option_rationales": {"a": "Incorreta. A VATS é útil no trauma estável ou tardio (hemotórax retido), não no sangramento exsanguinante ativo.", "b": "Incorreta. São medidas auxiliares, mas não substituem o controle cirúrgico do sangramento massivo.", "c": "Incorreta. A arteriografia pode ser útil em traumas pélvicos, mas no tórax com sangramento desse volume, a cirurgia é a prioridade.", "d": "Correta. Toracotomia de emergência está indicada pelo débito mantido elevado e choque.", "e": "Incorreta. O atraso na intervenção em um quadro de sangramento ativo instável é fatal."}, "difficulty": "dificil", "tags": ["Pneumologia", "Cirurgia de Trauma", "Hemotórax", "Indicações de Toracotomia"]}', 118, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A fístula quilosa (Quilotórax) pode levar a consequências metabólicas e imunológicas graves se não tratada precocemente. Qual é a principal alteração laboratorial sistêmica esperada em casos de quilotórax volumoso prolongado?", "options": {"a": "Alcalose metabólica hipoclorêmica.", "b": "Trombocitose reativa.", "c": "Hipernatremia e hipercalemia.", "d": "Linfopenia e Hipogamaglobulinemia.", "e": "Hipercolesterolemia grave."}, "answer": "d", "rationale": "A linfa é riquíssima em linfócitos T (principalmente T-helper) e imunoglobulinas. Pacientes com drenagem mantida de quilo perdem essas defesas, desenvolvendo linfopenia sistêmica profunda e redução de IGs séricas, o que aumenta drasticamente o risco de infecções oportunistas.", "option_rationales": {"a": "Incorreta. Pode haver acidose metabólica pela perda de bicarbonato na linfa.", "b": "Incorreta. Não há associação direta.", "c": "Incorreta. Perde-se eletrólitos, tendendo a hiponatremia se houver reposição hídrica apenas com água livre, mas não é a marca principal.", "d": "Correta. Consequência direta da perda do fluido linfático rico em imunidade celular e humoral.", "e": "Incorreta. Os lipídios estão sendo perdidos para fora da circulação sérica, não acumulados."}, "difficulty": "dificil", "tags": ["Pneumologia", "Quilotórax", "Fisiologia", "Imunidade"]}', 119, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A presença de ''pseudocilindros'' ou ''corpúsculos de grãos'' no líquido pleural pode ocorrer em casos de pleurite traumática crônica ou processos degenerativos de longa data. No entanto, o achado de células mesoteliais multinucleadas e gigantes é mais sugestivo de qual condição autoimune?", "options": {"a": "Poliarterite Nodosa.", "b": "Artrite Reumatoide (AR).", "c": "Dermatomiosite.", "d": "Lúpus Eritematoso Sistêmica (LES).", "e": "Esclerodermia Sistêmica."}, "answer": "b", "rationale": "O líquido pleural da Artrite Reumatoide possui achados citológicos peculiares, como a presença de macrófagos gigantes multinucleados e células alongadas (spindle cells), que representam restos de sinovite granulomatosa na pleura.", "option_rationales": {"a": "Incorreta. Vasculite de médios vasos, raramente acomete a pleura com este padrão.", "b": "Correta. Citologia característica da pleurite reumatoide.", "c": "Incorreta. Manifestação rara.", "d": "Incorreta. O LES apresenta as ''células LE'' e anticorpos específicos.", "e": "Incorreta. Esclerodermia causa mais fibrose pulmonar do que derrame exuberante."}, "difficulty": "dificil", "tags": ["Pneumologia", "Reumatologia", "Citologia Pleural", "Artrite Reumatoide"]}', 120, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Sobre o Derrame Pleural da Sarcoidose, assinale a correta.", "options": {"a": "Ocorre em mais da metade dos pacientes com sarcoidose estágio II.", "b": "A presença de derrame pleural exclui o diagnóstico de sarcoidose sistêmica.", "c": "É invariavelmente hemorrágico e cursa com glicose zero.", "d": "O líquido pleural é tipicamente um exsudato linfocítico com alta relação CD4/CD8.", "e": "O ADA pleural costuma ser superior a 100 U/L."}, "answer": "d", "rationale": "O derrame pleural na sarcoidose é raro (1-5% dos casos). Quando ocorre, é um exsudato linfocítico. Assim como no lavado broncoalveolar da sarcoidose, o líquido pleural apresenta uma relação entre linfócitos T CD4+ e CD8+ elevada (Geralmente > 3,5).", "option_rationales": {"a": "Incorreta. É uma manifestação incomum.", "b": "Incorreta. Não exclui, mas obriga a afastar TB e câncer pelo perfil linfocítico.", "c": "Incorreta. Não é hemorrágico nem consome glicose de forma acentuada.", "d": "Correta. Reflete o padrão de resposta imune Th1 da sarcoidose.", "e": "Incorreta. O ADA costuma ser baixo ou moderado, não atingindo os níveis da TB."}, "difficulty": "dificil", "tags": ["Pneumologia", "Sarcoidose", "Linfócitos", "CD4/CD8"]}', 121, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A fístula Colecistopleural é uma causa extremamente rara de derrame pleural. Qual a coloração característica do líquido pleural neste cenário clínico?", "options": {"a": "Hemorrágica.", "b": "Líquido viscoso transparente.", "c": "Leitosa.", "d": "Esverdeada ou amarelada (bile), com dosagem de Bilirrubina Pleural / Bilirrubina Sérica > 1,0.", "e": "Preta ou marrom escuro."}, "answer": "d", "rationale": "Também chamado de ''Biliotórax'', ocorre pela fístula entre o sistema biliar e o espaço pleural (frequentemente após trauma ou procedimentos hepáticos). A confirmação diagnóstica é a relação de bilirrubina pleural/sérica maior que 1, além do aspecto biliar do líquido.", "option_rationales": {"a": "Incorreta. Sangue na pleura.", "b": "Incorreta. Mesotelioma (ácido hialurônico).", "c": "Incorreta. Linfa ou colesterol.", "d": "Correta. Biliotórax diagnóstica bioquímica.", "e": "Incorreta. Infecção por Aspergillus niger ou ruptura de cisto melânico."}, "difficulty": "media", "tags": ["Pneumologia", "Gastroenterologia", "Bioquímica", "Biliotórax"]}', 122, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 62 anos, com diagnóstico de Melanoma Metastático em tratamento com Pembrolizumabe (anti-PD1), apresenta-se com dispneia e derrame pleural bilateral exsudativo, após 3 meses de terapia. Não há evidência de progressão tumoral nos outros sítios. A análise do líquido mostra linfocitose e ADA normal. Este quadro é compatível com:", "options": {"a": "Evento Adverso Imuno-Relacionado (irAE), manifestando-se como pleurite autoimune induzida pelo inibidor de checkpoint.", "b": "Toxicidade cardíaca direta pela quimioterapia convencional.", "c": "Empiema bacteriano.", "d": "Tuberculose reativada pela imunoterapia.", "e": "Progressão explosiva da doença (Pseudoprogressão)."}, "answer": "a", "rationale": "Inibidores de checkpoint (como Pembrolizumabe e Nivolumabe) podem causar inflamação em qualquer órgão, incluindo a pleura. O diagnóstico de pleurite imuno-relacionada é feito pela exclusão de causas infecciosas e neoplásicas, e o tratamento geralmente envolve a suspensão da droga e o uso de corticosteroides.", "option_rationales": {"a": "Correta. Manifestação moderna de toxicidade de novas terapias oncológicas.", "b": "Incorreta. Imunoterapia não é quimioterapia convencional; a disfunção cardíaca (miocardite) é rara e daria transudato.", "c": "Incorreta. Teria neutrofilia e pH baixo.", "d": "Incorreta. Embora possível, a imunoterapia não é o gatilho clássico para TB comparado a anti-TNF.", "e": "Incorreta. Pseudoprogressão é o aumento temporário do tumor antes da resposta, mas a pleurite isolada sem progressão nodal ou de massa é mais sugestiva de irAE."}, "difficulty": "dificil", "tags": ["Pneumologia", "Oncologia", "Imunoterapia", "Toxicidade"]}', 123, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "No diagnóstico diferencial de derrames pleurais exsudativos, a medição do pH pleural é mandatória. Qual o cuidado técnico ESSENCIAL para garantir a validade do resultado na gasometria do líquido pleural?", "options": {"a": "Usar apenas tiras reagentes de urina (dipstick) para leitura imediata.", "b": "Coletar o líquido em frasco de cultura aeróbia.", "c": "Adicionar soro fisiológico para diluir o excesso de proteínas.", "d": "Garantir a ausência total de contato do líquido com o ar ambiente e coletar em seringa heparinizada de gasometria.", "e": "Armazenar a amostra em temperatura ambiente por até 24 horas antes da análise."}, "answer": "d", "rationale": "O pH do líquido pleural deve ser medido em um gasômetro, utilizando seringas heparinizadas (preferencialmente de vidro ou plástico hermético). O contato com o ar ambiente leva à perda de CO2, o que eleva artificialmente o pH, falseando o diagnóstico de empiema ou complicação.", "option_rationales": {"a": "Incorreta. Tiras de urina são imprecisas para medir pH pleural e perdem a validade diagnóstica mínima necessária.", "b": "Incorreta. O frasco de cultura não mantém a vedação gasosa necessária para o pH.", "c": "Incorreta. A diluição altera o pH e a bioquímica.", "d": "Correta. Protocolo padrão para análise de pH pleural.", "e": "Incorreta. A análise deve ser imediata ou a amostra deve ser mantida em gelo seco por curto período."}, "difficulty": "media", "tags": ["Pneumologia", "Procedimentos", "pH Pleural", "Laboratório"]}', 124, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "O achado de células de um carcinoma espinocelular no líquido pleural, em comparação ao adenocarcinoma, é:", "options": {"a": "Sempre indicativo de empiema associado.", "b": "Muito mais comum.", "c": "Muito menos comum (raro), devido ao padrão de crescimento local/obstrutivo do CEC.", "d": "Inexistente, pois o CEC não causa derrame.", "e": "O critério diagnóstico para Mesotelioma."}, "answer": "c", "rationale": "O adenocarcinoma é periférico e invade a pleura precocemente, sendo a causa mais comum de derrame neoplásico citológico positivo. O carcinoma espinocelular (CEC) é central e causa mais atelectasias obstrutivas (transudatos por pressão negativa) do que invasão pleural direta (exsudatos), sendo raro encontrar células de CEC na citologia pleural.", "option_rationales": {"a": "Incorreta. Sem relação direta.", "b": "Incorreta. O adenocarcinoma domina a citologia pleural.", "c": "Correta. Diferença importante de comportamento biológico dos tumores de pulmão.", "d": "Incorreta. Pode causar, mas é infrequente.", "e": "Incorreta. Mesotelioma tem origem mesotelial, não escamosa/espinocelular."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "Derrame Neoplásico", "CEC"]}', 125, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "No diagnóstico da etiologia do derrame pleural, o uso de biomarcadores como a Procalcitonina no líquido pleural (e não no soro) apresenta qual evidência atual?", "options": {"a": "Indica obrigatoriamente etiologia por Legionella.", "b": "Substitui a dosagem de pH e glicose com vantagem.", "c": "Possui baixa utilidade clínica comprovada, não sendo superior aos parâmetros bioquímicos tradicionais (pH, glicose, LDH).", "d": "É o melhor marcador para distinguir Tuberculose de Câncer.", "e": "É mandatório em todos os transudatos cardíacos."}, "answer": "c", "rationale": "Diferente da Procalcitonina sérica (útil na sepse), a Procalcitonina no líquido pleural tem demonstrado baixo valor agregado. Ela não diferencia de forma confiável o empiema de outros exsudatos inflamatórios melhor do que o pH ou o LDH.", "option_rationales": {"a": "Incorreta. Sem relação específica.", "b": "Incorreta. pH e glicose permanecem superiores.", "c": "Correta. Evidência clínica atual desencoraja o uso rotineiro do biomarcador pleural.", "d": "Incorreta. Sem utilidade neste diferencial.", "e": "Incorreta. Sem aplicação em transudatos."}, "difficulty": "dificil", "tags": ["Pneumologia", "Biomarcadores", "Evidência", "Procalcitonina"]}', 126, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Em pacientes submetidos à diálise peritoneal, a ocorrência de derrame pleural volumoso à direita (''Hidrotórax doce'') é causada pela fístula pleuro-peritoneal. Por qual motivo a coloração de Gram e a cultura do líquido pleural devem ser realizadas nestes pacientes, mesmo com suspeita de transudato?", "options": {"a": "Para rastrear peritonite bacteriana que pode ter translocado junto com o dialisado através da fístula diafragmática.", "b": "Porque pacientes em diálise têm alta taxa de colonização pleural por fungos.", "c": "A glicose alta atrai bactérias da pele durante a toracentese.", "d": "Para confirmar o ''gosto'' doce do líquido.", "e": "É uma rotina administrativa desnecessária clínica."}, "answer": "a", "rationale": "A fístula diafragmática permite que não apenas o líquido de diálise, mas também qualquer processo infeccioso peritoneal (peritonite por contaminação do cateter de diálise) se espalhe para a pleura, transformando um hidrotórax mecânico em um empiema/pleurite bacteriana.", "option_rationales": {"a": "Correta. Raciocínio clínico sobre fístulas serosas.", "b": "Incorreta. Menos comum que a bacteriana.", "c": "Incorreta. Explicação fictícia.", "d": "Incorreta.", "e": "Incorreta. Tem valor diagnóstico e terapêutico."}, "difficulty": "media", "tags": ["Pneumologia", "Nefrologia", "Diálise", "Peritonite"]}', 127, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Ao avaliar uma tomografia de tórax de um paciente com dor torácica incaracterística, percebe-se um espessamento isolado da pleura mediastinal à esquerda. Qual a significância deste achado radiológico?", "options": {"a": "Sempre indica neoplasia agressiva.", "b": "Indica perfuração de brônquio fonte.", "c": "É um achado inespecífico, frequentemente relacionado a gordura epicárdica ou mediastinal exuberante.", "d": "Sinal patognomônico de asbestose.", "e": "Sugerido como local de biópsia para amiloidose."}, "answer": "c", "rationale": "O ''espessamento'' pleural na região mediastinal ou paravertebral é frequentemente simulado pelo acúmulo de gordura extrapleural. É um achado comum e geralmente benigno, a menos que seja nodular ou associado a derrame pleural ou massas mediastinais reais.", "option_rationales": {"a": "Incorreta. O diagnóstico mais comum é lipomatose mediastinal/extrapleural.", "b": "Incorreta. Perfuração brônquica causaria pneumomediastino rápido.", "c": "Correta. Pista radiológica para evitar pânico diagnóstico.", "d": "Incorreta. Asbestose atinge a pleura parietal lateral e o diafragma, não a mediastinal isolada.", "e": "Incorreta. Amiloidose pleural é rara e não se baseia nesse achado isolado."}, "difficulty": "media", "tags": ["Pneumologia", "Radiologia", "Anatomia", "Variantes"]}', 128, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A toracentese deve ser evitada ou postergada em qual das seguintes condições clínicas, devido ao risco aumentado de complicações hemorrágicas severas?", "options": {"a": "Uso de Aspirina 100mg/dia (Antiagregante plaquetário).", "b": "Nível de Creatinina sérica > 6,0 mg/dL (Insuficiência Renal Crônica).", "c": "Derrame pleural loculado evidenciado por ultrassom.", "d": "Presença de ventilação mecânica com PEEP de 10 cmH2O.", "e": "Contagem de plaquetas < 50.000/mm³ ou INR > 2,0."}, "answer": "e", "rationale": "Embora a toracentese seja um procedimento seguro, contagens de plaquetas abaixo de 50.000 ou coagulopatias severas (INR > 2) aumentam o risco de hemotórax iatrogênico. Nessas condições, as diretrizes sugerem corrigir os níveis antes do procedimento ou realizar com auxílio de ultrassom e extrema cautela.", "option_rationales": {"a": "Incorreta. O uso de aspirina isolada não exige suspensão para toracentese diagnóstica.", "b": "Incorreta. A uremia afeta a função plaquetária, mas não é contraindicação absoluta por si só.", "c": "Incorreta. O derrame loculado é justamente um alvo para toracentese guiada por imagem.", "d": "Incorreta. Ventilação mecânica exige cuidado, mas não é contraindicação; o US ajuda a evitar pneumotórax.", "e": "Correta. Plaquetopenia e INR elevado são marcos de risco hemorrágico elevado."}, "difficulty": "dificil", "tags": ["Pneumologia", "Toracentese", "Segurança do Paciente", "Hematologia"]}', 129, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Asbestose'' associada ao ''Derrame Pleural Benigno do Asbesto'' (BAPE) é caracterizada pela presença de qual tipo de fibra de amianto que possui maior potencial carcinogênico e de irritação pleural devido à sua forma longa e rígida?", "options": {"a": "Sílica cristalina.", "b": "Crisotila (Amianto Branco).", "c": "Fibras de Carbono.", "d": "Gesso sintético.", "e": "Anfibólios (ex: Crocidolita ou Amianto Azul)."}, "answer": "e", "rationale": "Embora a crisotila seja a mais utilizada comercialmente, os anfibólios (como a crocidolita e a amosita) são fibras retas, rígidas e finas que penetram profundamente no pulmão e alcançam a pleura com maior facilidade, apresentando maior potencial para causar mesotelioma e derrames benignos.", "option_rationales": {"a": "Incorreta. Causa silicose (parênquima e linfonodo), raramente derrame isolado.", "b": "Incorreta. Menos persistente no tecido pleural que o anfibólio.", "c": "Incorreta. Fibras modernas com baixo potencial de patogenicidade pleural comparada ao asbesto.", "d": "Incorreta. Não causa patologia pleural clássica por fibras.", "e": "Correta. Tipo de amianto mais agressivo para a pleura."}, "difficulty": "dificil", "tags": ["Pneumologia", "Doença Ocupacional", "Asbesto", "Toxicologia"]}', 130, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente tabagista com câncer de pulmão apresenta-se com Síndrome da Veia Cava Superior (SVCS). Ele desenvolve derrame pleural bilateral. A análise do líquido revela um TRANSUDATO. Qual o mecanismo?", "options": {"a": "Metástase pleural massiva.", "b": "Desnutrição neoplásica grave.", "c": "Aumento da pressão hidrostática nos capilares pleurais devido à obstrução da drenagem venosa sistêmica cranial (veias braquiocefálicas/cava superior).", "d": "Pneumonia pós-obstrutiva.", "e": "Insuficiência cardíaca direita por TEP."}, "answer": "c", "rationale": "A SVCS aumenta a pressão hidrostática nas veias que drenam a pleura parietal superior e mediastinal. Isso pode gerar um transudato puramente mecânico, independente da presença de metástases pleurais. Ao tratar a obstrução (stent ou radio), o derrame costuma desaparecer.", "option_rationales": {"a": "Incorreta. Metástase daria exsudato.", "b": "Incorreta. Desnutrição (hipoalbuminemia) daria transudato, mas a SVCS é uma causa mecânica mais direta neste contexto.", "c": "Correta. Mecanismo hidrostático clássico da obstrução venosa central.", "d": "Incorreta. Pneumonia daria exsudato parapneumônico.", "e": "Incorreta. Hipótese menos provável se houver sinais claros de obstrução de cava (turgência jugular que não pulsa, edema em escravina)."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "SVCS", "Mecanismo"]}', 131, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 30 anos, HIV positivo, apresenta febre, perda ponderal e derrame pleural linfocítico (90% linfócitos). O ADA é de 35 U/L (valor de corte local = 40 U/L). A biópsia pleural por agulha revela inflamação crônica inespecífica, sem granulomas ou BAAR. Qual a conduta mais racional diante desse quadro inconclusivo?", "options": {"a": "Encaminhar para Videotoracoscopia (VATS) para biópsia dirigida.", "b": "Solicitar TRM-TB (Teste Rápido Molecular) e cultura para micobactérias no líquido pleural.", "c": "Descartar Tuberculose e investigar Linfoma Pleural.", "d": "Iniciar o tratamento empírico para Tuberculose Pleural.", "e": "Repetir a biópsia pleural por agulha de Abrams em outro sítio."}, "answer": "b", "rationale": "Em pacientes com HIV, a apresentação da TB pleural pode ser atípica (ADA mais baixo) e o rendimento da biópsia cega é menor. Antes de procedimentos invasivos como VATS, deve-se esgotar a investigação microbiológica (cultura em meio líquido e teste rápido molecular), que no HIV tem rendimento superior ao esperado na população imunocompetente.", "option_rationales": {"a": "Incorreta. A VATS é o próximo passo se a microbiologia falhar, mas é mais invasiva.", "b": "Correta. Cultura e TRM-TB são mandatórios para aumentar a sensibilidade no paciente HIV.", "c": "Incorreta. A TB ainda é o principal suspeito, mesmo com ADA levemente baixo no HIV.", "d": "Incorreta. O tratamento empírico deve ser reservado para quando os exames microbiológicos falham.", "e": "Incorreta. Repetir biópsia cega não costuma elevar muito o rendimento após a primeira negativa."}, "difficulty": "dificil", "tags": ["Pneumologia", "HIV", "Tuberculose Pleural", "Diagnóstico"]}', 132, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Em qual situação o gradiente de albumina (Soro - Pleura) é superior aos critérios de Light para o diagnóstico da causa do derrame?", "options": {"a": "Pacientes com Insuficiência Cardíaca que fizeram uso prévio de diuréticos.", "b": "Qualquer derrame bilateral.", "c": "Suspeita de Tuberculose Pleural.", "d": "Suspeita de Empiema.", "e": "Pacientes com câncer de pulmão metastático."}, "answer": "a", "rationale": "Os diuréticos removem água do espaço pleural mais rápido que as proteínas, ''concentrando'' o transudato e transformando-o em um exsudato pelos critérios de Light. O gradiente de albumina (> 1,2 mg/dL) ignora essa concentração e identifica corretamente a origem cardíaca.", "option_rationales": {"a": "Correta. Indicação clássica para uso de gradiente.", "b": "Incorreta. Nem todo derrame bilateral é cardíaco.", "c": "Incorreta. TB é exsudato verdadeiro; o gradiente será baixo.", "d": "Incorreta. Empiema é exsudato verdadeiro.", "e": "Incorreta. Câncer é exsudato verdadeiro."}, "difficulty": "facil", "tags": ["Pneumologia", "Laboratório", "ICC", "Critérios de Light"]}', 133, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A decorticação pulmonar por videotoracoscopia ou toracotomia está indicada primariamente em qual fase do empiema pleural?", "options": {"a": "Fase Exsudativa (Líquid fluido, pH normal).", "b": "Fase de Organização (Pulmão encarcerado por carapaça fibrosa sólida).", "c": "Fase Fibrinopurulenta inicial (pH < 7,2, mas sem septos densos).", "d": "Apenas em pacientes imunocomprometidos.", "e": "Sempre no primeiro dia de internação de qualquer empiema."}, "answer": "b", "rationale": "A decorticação é a remoção da ''casca'' de fibrina e tecido fibroso que se forma sobre a pleura visceral na fase de organização (última fase do empiema). É indicada quando a drenagem tubular falha em reexpandir o pulmão devido a esse encarceramento.", "option_rationales": {"a": "Incorreta. Fase inicial, trata-se apenas com dreno ou antibiótico.", "b": "Correta. Indicação clássica de cirurgia para ''soltar'' o pulmão.", "c": "Incorreta. Nesta fase tentam-se fibrinolíticos antes da cirurgia agressiva.", "d": "Incorreta. Indicação baseada na fase da pleurite, não no status imune isolado.", "e": "Incorreta. Conduta exagerada."}, "difficulty": "media", "tags": ["Pneumologia", "Cirurgia Torácica", "Empiema", "Decorticação"]}', 134, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ocorrência de derrame pleural purulento ''verde-azulado'' pode ser indicativa de infecção por qual bactéria gram-negativa oportunista?", "options": {"a": "Haemophilus influenzae.", "b": "Pseudomonas aeruginosa (devido à produção de pigmentos como piocianina e pioverdina).", "c": "Moraxella catarrhalis.", "d": "Streptococcus pneumoniae.", "e": "Escherichia coli."}, "answer": "b", "rationale": "A Pseudomonas produz pigmentos coloridos que podem tingir o pus do empiema. É uma pista macroscópica importante para o início de cobertura antibiótica antipseudomonas precoce enquanto se aguarda o antibiograma.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Pista microbiológica macroscópica clássica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Pneumologia", "Infectologia", "Pseudomonas", "Pigmentos"]}', 135, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Sobre a ''Linfocitose Pleural'' (> 50-80%), qual a causa MAIS COMUM em países com alta prevalência de Tuberculose?", "options": {"a": "Sarcoidose.", "b": "Linfoma.", "c": "Tuberculose Pleural.", "d": "Cancer de pulmão.", "e": "Artrite Reumatoide."}, "answer": "c", "rationale": "Embora o câncer e o linfoma também causem linfocitose, em países endêmicos para Mycobacterium tuberculosis como o Brasil, a TB pleural é estatisticamente a causa número 1 de exsudato linfocítico persistente em jovens e adultos jovens.", "option_rationales": {"a": "Incorreta. Rara no Brasil comparada à TB.", "b": "Incorreta. Mais raro comparado à TB.", "c": "Correta. Epidemiologia clássica.", "d": "Incorreta. Comum, mas TB supera em incidência de linfocitose em muitos cenários brasileiros.", "e": "Incorreta. Causa importante, mas menos frequente."}, "difficulty": "facil", "tags": ["Pneumologia", "Epidemiologia", "Tuberculose", "Linfocitose"]}', 136, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Em pacientes com ''Insuficiência Renal Crônica'' em hemodiálise, o aparecimento de derrame pleural transudativo súbito BILATERAL, associado a aumento do peso entre as sessões, sugere:", "options": {"a": "Carcinomatose.", "b": "Infeção pelo vírus da Hepatite C.", "c": "Urinotórax.", "d": "Hipervolemia por falha na remoção de fluidos (Congestão sistêmica).", "e": "Pleurite por alumínio."}, "answer": "d", "rationale": "Pacientes anúricos dependem totalmente da ultrafiltração na diálise. O ganho de peso interdialítico excessivo leva à sobrecarga volêmica, aumento da pressão hidrostática e consequente transudação pleural (edema ''interno''). Melhora com ajuste de peso seco na diálise.", "option_rationales": {"a": "Incorreta. Daria exsudato.", "b": "Incorreta.", "c": "Incorreta. Urinotórax é unilateral e associado a obstrução urinária aguda com rim funcionante.", "d": "Correta. Causa diária e comum na nefrologia.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Pneumologia", "Nefrologia", "Hemodiálise", "Hipervolemia"]}', 137, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Pleurite Lúpica'' apresenta como achado característico no líquido pleural a presença de células LE (Lupus Erythematosus cells). O que são essas células?", "options": {"a": "Células musculares lisas.", "b": "Fragmentos de talco.", "c": "Linfócitos gigantes atípicos.", "d": "Neutrófilos ou macrófagos que fagocitaram núcleos desnaturalizados de outras células (material nuclear opsonizado por anticorpos anti-nucleares).", "e": "Bactérias em forma de lobo."}, "answer": "d", "rationale": "Embora o diagnóstico moderno do LES se baseie em anticorpos específicos (FAN, anti-DNA, etc), a visualização de células LE no líquido pleural é um achado histórico e raro, mas altamente sugestivo de pleurite lúpica ativa.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta.", "c": "Incorreta.", "d": "Correta. Definição citológica clássica.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Pneumologia", "Reumatologia", "LES", "Células LE"]}', 138, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A biópsia pleural por videotoracoscopia (VATS) é considerada o padrão-ouro para o diagnóstico de derrames pleurais exsudativos de difícil diagnóstico. Qual a sensibilidade aproximada deste procedimento para a detecção de malignidade?", "options": {"a": "95-98%.", "b": "60-70%.", "c": "100%, sem possibilidade de erro.", "d": "Apenas 50%, pois só visualiza a pleura parietal.", "e": "80-85%."}, "answer": "a", "rationale": "A VATS permite a visualização direta de toda a cavidade pleural e a coleta de biópsias dirigidas das áreas mais suspeitas. Sua sensibilidade para malignidade é extremamente alta, aproximando-se de 100%.", "option_rationales": {"a": "Correta. Eficácia diagnóstica superior na pleura.", "b": "Incorreta. Este é o valor da biópsia cega.", "c": "Incorreta. Embora rara, a falha pode ocorrer em casos de aderências totais que impeditam a visualização (espaço pleural sínfise).", "d": "Incorreta. Visualiza parietal, visceral e diafragma.", "e": "Incorreta. Valor baixo para VATS."}, "difficulty": "media", "tags": ["Pneumologia", "VATS", "Diagnóstico", "Oncologia"]}', 139, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 25 anos apresenta quadro de febre, tosse produtiva e derrame pleural à esquerda. A toracentese revela líquido purulento e espesso. A ultrassonografia mostra a pleura visceral ''balançando'' em sincronia com os batimentos cardíacos, sinal conhecido como ''Sinal do Pulso''. Qual o significado clínico deste achado ultrassonográfico?", "options": {"a": "Representa a presença de ar intrapleural (hidropneumotórax).", "b": "Indica empiema na fase aguda com perfuração pericárdica iminente.", "c": "Sugere atelectasia total do pulmão subjacente (ausência de respiração e presença de transmissão de pulso cardíaco).", "d": "Indica que o líquido pleural é de baixa densidade (transudato).", "e": "É um sinal clássico de pneumonia necrotizante com fístula broncopleural."}, "answer": "c", "rationale": "O ''Static B-lines'' associado ao ''Lung Pulse'' na ultrassonografia pulmonar indica que o pulmão não está ventilando (atelectasia), mas o parênquima ainda está em contato com o mediastino, transmitindo as pulsações cardíacas. No contexto de empiema ou derrame pleural massivo, sugere que o parênquima adjacente está colapsado e não aerado.", "option_rationales": {"a": "Incorreta. Ar na pleura (pneumotórax) abole o lung pulse e todas as outras linhas pulmonares pela ausência de contato pleura-pleura.", "b": "Incorreta. Não indica risco de perfuração pericárdica.", "c": "Correta. O sinal do pulso é característico de pulmão consolidado/atelectasiado sem ventilação.", "d": "Incorreta. É um achado de parênquima/consolidação, não do líquido em si.", "e": "Incorreta. A fístula broncopleural costuma dar o sinal da ''cauda de cometa'' ou pontos de ar móveis."}, "difficulty": "dificil", "tags": ["Pneumologia", "Ultrassonografia", "Semiologia", "Atelectasia"]}', 140, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "O Mesotelioma Peritoneal Maligno se manifesta por ascite e dor abdominal. Qual a relação dele com a exposição ao asbesto em comparação ao Mesotelioma Pleural?", "options": {"a": "O peritoneal não tem relação com o asbesto.", "b": "O peritoneal exige cargas de exposição ao asbesto muito maiores que o pleural.", "c": "O peritoneal é curado com antibióticos.", "d": "O peritoneal ocorre mais em mulheres que nunca viram amianto.", "e": "São doenças idênticas em todos os aspectos epidemiológicos."}, "answer": "b", "rationale": "Ambos são causados pelo asbesto, mas o mesotelioma peritoneal (que representa cerca de 10-15% dos mesoteliomas) geralmente está associado a exposições ocupacionais pesadas e prolongadas, enquanto o pleural pode ocorrer com exposições menores.", "option_rationales": {"a": "Incorreta. Amianto é a causa principal de ambos.", "b": "Correta. Diferença de ''threshold'' de exposição entre as duas serosas.", "c": "Incorreta. É uma neoplasia maligna agressiva.", "d": "Incorreta. Predomina em homens expostos ocupacionalmente.", "e": "Incorreta. Locais diferentes, prognóstico e algoritmos de tratamento cirúrgico (ex: HIPEC no peritoneal) diferentes."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "Mesotelioma Peritoneal", "Asbesto"]}', 141, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente tabagista crônico apresenta derrame pleural volumoso. A toracentese revela líquido âmbar, límpido. Bioquímica: Glicose 95, Proteína 4,2 (Sérica 6,8), LDH 520 (Sérico 300). Citologia: Predomínio de linfócitos (92%), células mesoteliais raras, ausência de células malignas. ADA 25 U/L. Biópsia de Abrams: Inflamação crônica inespecífica. Próximo passo recomendado por diretrizes?", "options": {"a": "Novo ciclo de antibióticos por 14 dias.", "b": "Pesquisa de células LE no líquido pleural.", "c": "Videotoracoscopia (VATS) com biópsias dirigidas.", "d": "Acompanhamento radiológico em 1 ano.", "e": "Tratamento empírico para Tuberculose."}, "answer": "c", "rationale": "O paciente possui um exsudato linfocítico com ADA intermediário e biópsia cega negativa. Em um fumante idoso, a suspeita de câncer é alta e a biópsia de Abrams negativa não exclui a doença. O próximo passo é a biópsia dirigida por VATS.", "option_rationales": {"a": "Incorreta. Não há sinais de infecção bacteriana (glicose normal, líquido límpido).", "b": "Incorreta. Lúpus não é o diagnóstico principal para este perfil clínico.", "c": "Correta. Conduta padrão para exsudatos linfocíticos não resolvidos.", "d": "Incorreta. Tempo muito longo para risco de neoplasia.", "e": "Incorreta. O ADA é baixo (25) e o paciente é fumante, câncer é prioritário."}, "difficulty": "media", "tags": ["Pneumologia", "Fluxograma Diagnóstico", "VATS", "Oncologia"]}', 142, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A dosagem de interferon-gama (IFN-γ) no líquido pleural tem sido estudada como alternativa à dosagem de ADA para o diagnóstico de tuberculose pleural. Em comparação ao ADA, o INF-γ costuma apresentar:", "options": {"a": "Resultado sempre negativo em pacientes HIV positivos.", "b": "Falsos-positivos frequentes em transudatos cardíacos.", "c": "Menor sensibilidade e maior custo.", "d": "Inutilidade total, sendo inferior em todos os parâmetros.", "e": "Maior especificidade, porém custo mais elevado e menor disponibilidade."}, "answer": "e", "rationale": "O interferon-gama pleural tem acurácia diagnóstica excelente para TB, por vezes superior ao ADA em especificidade. No entanto, devido ao alto custo e à complexidade laboratorial, o ADA permanece como o exame de escolha na prática clínica (custo-efisicácia superior).", "option_rationales": {"a": "Incorreta. Pode ser positivo no HIV, embora a carga linfocitária possa influenciar o nível absoluto.", "b": "Incorreta. Ele é muito específico para inflamação granulomatosa/TB.", "c": "Incorreta. A sensibilidade também é muito alta.", "d": "Incorreta. É um ótimo teste científico.", "e": "Correta. Desempenho excelente, mas custo e acesso são barreiras."}, "difficulty": "dificil", "tags": ["Pneumologia", "Tuberculose", "Biomarcadores", "IFN-gama"]}', 143, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "O ''Derrame Pleural Paraneoplásico'' (Efusão Paramaligna) difere da Efusão Maligna Verdadeira porque:", "options": {"a": "Só ocorre em crianças.", "b": "É sempre purulento.", "c": "O paraneoplásico é causado pelo talco.", "d": "O paraneoplásico ocorre por mecanismos indiretos (obstrução linfática regional, pneumonia obstrutiva ou hipoalbuminemia) e NÃO contém células neoplásicas na pleura ou no líquido.", "e": "Cura-se com aspirina."}, "answer": "d", "rationale": "Essa distinção é vital para o estadiamento. Se o líquido for paraneoplásico (células malignas negativas em múltiplas citologias e biópsias), o paciente ainda pode ser candidato a tratamento curativo (estágio menor). Se for maligno (M1a), o tratamento é paliativo.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta.", "c": "Incorreta.", "d": "Correta. Definição oncológica fundamental para estadiamento (M0 vs M1).", "e": "Incorreta."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "Estadiamento", "Mecanismo"]}', 144, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "No diagnóstico de amiloidose sistêmica com acometimento pleural, qual o achado padrão-ouro na biópsia pleural?", "options": {"a": "Granulomas não caseificantes.", "b": "Presença de corpúsculos de ferrugem (Asbestos bodies).", "c": "Deposição de material amorfo eosinofílico com birrefringência verde-maçã sob luz polarizada após coloração de Vermelho Congo.", "d": "Fibrina densa com neutrófilos.", "e": "Invasão de células musculares lisas atípicas."}, "answer": "c", "rationale": "A amiloidose pleural é uma causa rara de exsudato linfocítico crônico. O diagnóstico exige a biópsia (parietal ou pulmonar) com a coloração de Vermelho Congo, demonstrando a birrefringência clássica do material amiloide.", "option_rationales": {"a": "Incorreta. Característico da sarcoidose.", "b": "Incorreta. Indica exposição ao asbesto.", "c": "Correta. Padrão-ouro histopatológico para amiloidose.", "d": "Incorreta. Indica empiema organizado.", "e": "Incorreta. Característico da Linfangioleiomiomatose (LAM)."}, "difficulty": "media", "tags": ["Pneumologia", "Patologia", "Amiloidose", "Biópsia Pleural"]}', 145, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Pleurite Renal'' é uma manifestação do Lúpus Eritematoso Sistêmico (LES). Entretanto, o termo ''Derrame Pleural Urêmico'' refere-se especificamente a:", "options": {"a": "Exsudato fibrinoso em pacientes com insuficiência renal avançada sem outra causa explicável.", "b": "Derrame pleural por nefrose lipoídica.", "c": "Transudato por hipoalbuminemia nefrótica.", "d": "Acúmulo de urina na pleura por ruptura de ureter (Urinotórax).", "e": "Empiema por fístula nefropleural."}, "answer": "a", "rationale": "A pleurite urêmica ocorre em pacientes com ureia muito elevada (geralmente > 100 mg/dL). É um exsudato fibrinoso e muitas vezes hemorrágico. O tratamento é a diálise intensiva, que leva à resolução do derrame na maioria das vezes. Deve-se distinguir do urinotórax (urina na pleura).", "option_rationales": {"a": "Correta. Entidade inflamatória clássica da uremia severa.", "b": "Incorreta. Nefrose causa transudato.", "c": "Incorreta. Isso é transudato da síndrome nefrótica.", "d": "Incorreta. Isso é urinotórax.", "e": "Incorreta. Condição rara (fístula), não relacionada à síndrome urêmica metabólica."}, "difficulty": "dificil", "tags": ["Pneumologia", "Nefrologia", "Uremia", "Pleurite"]}', 146, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "No diagnóstico diferencial de nódulos pleurais, a Tomografia por Emissão de Pósitrons (PET-CT) com FDG-18 pode apresentar resultados FALSO-POSITIVOS (captação aumentada sem câncer) em qual das seguintes situações prévias?", "options": {"a": "Uso de corticoides inalatórios.", "b": "Toracocentese diagnóstica realizada há 1 ano.", "c": "Histórico de pleurodese com talco (Talc Poudrage ou Slurry) realizada anteriormente.", "d": "Derrame pleural transudativo por ICC.", "e": "Vacinação contra influenza."}, "answer": "c", "rationale": "O talco induz uma reação inflamatória granulomatosa crônica na pleura que é metabolicamente ativa e pode captar FDG intensamente no PET-CT por muitos anos. Isso dificulta a detecção de recidivas tumorais ou novos nódulos malignos na pleura ''talcada''.", "option_rationales": {"a": "Incorreta. Corticoides podem até reduzir a captação inflamatória.", "b": "Incorreta. Cicatriz mínima sem atividade metabólica persistente.", "c": "Correta. Causa clássica de falso-positivo em PET torácico.", "d": "Incorreta. Transudatos não captam FDG.", "e": "Incorreta. Sem relação com a pleura."}, "difficulty": "media", "tags": ["Pneumologia", "Medicina Nuclear", "PET-CT", "Pleurodese"]}', 147, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A fístula pleuroperitoneal em pacientes com ascite por cirrose Child-Pugh C geralmente leva a um hidrotórax localizado em qual hemitórax?", "options": {"a": "Direito em cerca de 75-85% dos casos.", "b": "Bilateral em todos os casos.", "c": "Apenas na base do pulmão esquerdo.", "d": "Exclusivamente mediastinal.", "e": "Esquerdo em 90% dos casos."}, "answer": "a", "rationale": "O hidrotórax hepático é predominantemente à direita. Isso ocorre porque o hemidiafragma direito é anatomicamente mais propenso a defeitos congênitos ou fendas adquiridas, e a pressão negativa intratorácica ''puxa'' a ascite do abdome para o tórax por esses trajetos.", "option_rationales": {"a": "Correta. Localização preferencial anatomofisiológica.", "b": "Incorreta. Costuma ser unilateral pela localização da fístula.", "c": "Incorreta. Não é o padrão.", "d": "Incorreta. Não ocorre no mediastino.", "e": "Incorreta. Inverso da estatística real."}, "difficulty": "facil", "tags": ["Pneumologia", "Gastroenterologia", "Hidrotórax Hepático", "Cirrose"]}', 148, 'draft');
INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A atelectasia redonda (Round Atelectasis) é uma forma de colapso pulmonar periférico associada a doenças pleurais crônicas (ex: asbesto). Qual é o sinal radiográfico característico na tomografia computadorizada que confirma o diagnóstico?", "options": {"a": "Broncograma de substituição.", "b": "Cavitação em ''meia lua''.", "c": "Sinal da Cauda de Cometa (Comet Tail Sign) - vasos e brônquios curvando-se para dentro da massa.", "d": "Sinal do Brônquio aéreo no centro da massa.", "e": "Sinal do Halo (Halo Sign)."}, "answer": "c", "rationale": "O ''Comet Tail Sign'' é a marca da atelectasia redonda. Representa a confluência de vasos e brônquios que são ''puxados'' e curvados em direção ao foco de parênquima colapsado por baixo da pleura espessada. É crucial para distinguir de câncer de pulmão.", "option_rationales": {"a": "Incorreta. Termo não utilizado.", "b": "Incorreta. Sugere aspergiloma (bola fúngica).", "c": "Correta. Sinal clássico da atelectasia por asbesto.", "d": "Incorreta. Comum em pneumonia, não específico da atelectasia redonda.", "e": "Incorreta. Sugere aspergilose angioinvasiva."}, "difficulty": "media", "tags": ["Pneumologia", "Radiologia", "Asbesto", "Atelectasia Redonda"]}', 149, 'draft');
